ALTER TABLE t_phm_rule_param_meta DROP CONSTRAINT IF EXISTS ck_phm_param_src;

UPDATE t_phm_rule_param_meta p
SET data_source = CASE
  WHEN p.param_col IN ('SJSD', 'CC') THEN 'LKJ'
  WHEN p.data_source IN ('HBASE', 'HBASE_PHM') THEN 'TCMS'
  WHEN p.data_source = 'HBASE_6A' THEN '6A'
  WHEN p.data_source = 'HBASE_LKJ' THEN 'LKJ'
  WHEN p.data_source = 'KAFKA' THEN 'DWD'
  ELSE p.data_source
END,
    hbase_table = CASE
        WHEN p.hbase_table LIKE '%机车维表%' OR p.hbase_table LIKE '事件%' THEN '-'
        ELSE p.hbase_table
    END,
    subsystem = (
  SELECT s.subsystem FROM tmp_sub s
  WHERE s.param_col = p.param_col AND s.hbase_table = REPLACE(REPLACE(p.hbase_table, '(待确认)', ''), '（待确认）', '')
),
    hide_reason = CASE
  WHEN p.param_name LIKE '%预留%' THEN 'RESERVED'
  WHEN (
  SELECT s.subsystem FROM tmp_sub s
  WHERE s.param_col = p.param_col AND s.hbase_table = REPLACE(REPLACE(p.hbase_table, '(待确认)', ''), '（待确认）', '')
) = '公共基础' THEN 'HEADER'
  ELSE NULL
END,
    is_hidden = CASE WHEN (CASE
  WHEN p.param_name LIKE '%预留%' THEN 'RESERVED'
  WHEN (
  SELECT s.subsystem FROM tmp_sub s
  WHERE s.param_col = p.param_col AND s.hbase_table = REPLACE(REPLACE(p.hbase_table, '(待确认)', ''), '（待确认）', '')
) = '公共基础' THEN 'HEADER'
  ELSE NULL
END) IS NULL THEN 0 ELSE 1 END,
    protocol_id = (
        SELECT pr.id FROM t_phm_rule_protocol pr
        WHERE pr.protocol_code = (CASE
  WHEN p.param_col IN ('CC', 'SJSD', 'TRAIN_STATUS') THEN 'DWD'
  WHEN p.param_col = 'IS_ZDX' THEN 'DIM'
  ELSE (SELECT m.protocol_code FROM tmp_table_map m WHERE m.hbase_table = REPLACE(REPLACE(p.hbase_table, '(待确认)', ''), '（待确认）', ''))
END)
    ),
    update_by = 'migrate',
    update_time = CURRENT_TIMESTAMP;

ALTER TABLE t_phm_rule_param_meta DROP CONSTRAINT IF EXISTS ck_phm_param_src;
ALTER TABLE t_phm_rule_param_meta
    ADD CONSTRAINT ck_phm_param_src CHECK (data_source IN ('TCMS', '6A', 'LKJ', 'DWD', 'DIM'));

ALTER TABLE t_phm_rule_param_meta DROP CONSTRAINT IF EXISTS ck_phm_param_hide;
ALTER TABLE t_phm_rule_param_meta
    ADD CONSTRAINT ck_phm_param_hide CHECK (is_hidden IN (0, 1));

ALTER TABLE t_phm_rule_param_meta DROP CONSTRAINT IF EXISTS ck_phm_param_hreason;
ALTER TABLE t_phm_rule_param_meta
    ADD CONSTRAINT ck_phm_param_hreason CHECK (hide_reason IS NULL OR hide_reason IN ('RESERVED', 'HEADER'));

ALTER TABLE t_phm_rule_param_meta DROP CONSTRAINT IF EXISTS fk_phm_param_protocol;
ALTER TABLE t_phm_rule_param_meta
    ADD CONSTRAINT fk_phm_param_protocol FOREIGN KEY (protocol_id) REFERENCES t_phm_rule_protocol (id);

COMMENT ON COLUMN t_phm_rule_param_meta.scope_cx IS '【废弃】适用车型，ALL 或逗号分隔。本版保留列，查询不再使用，改由 t_phm_rule_protocol_cx 按协议过滤';
COMMENT ON COLUMN t_phm_rule_param_meta.protocol_id IS '所属协议。车型过滤走协议与车型关系';
COMMENT ON COLUMN t_phm_rule_param_meta.subsystem IS '所属子系统。带(扩展)的名称已并回主名称';
COMMENT ON COLUMN t_phm_rule_param_meta.is_hidden IS '1 不出现在参数下拉，数据仍保留';
COMMENT ON COLUMN t_phm_rule_param_meta.hide_reason IS 'RESERVED 预留 / HEADER 帧头（公共基础）';
COMMENT ON COLUMN t_phm_rule_param_meta.data_source IS '数据源：TCMS / 6A / LKJ / DWD / DIM。DWD 页面称故障实时字段';

-- 索引已存在时匿名块吞掉错误，已经迁过的库再跑也安全。
\set SQLTERM /
BEGIN
    EXECUTE IMMEDIATE 'CREATE INDEX idx_phm_param_protocol ON t_phm_rule_param_meta (protocol_id)';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/
BEGIN
    EXECUTE IMMEDIATE 'CREATE INDEX idx_phm_param_hidden ON t_phm_rule_param_meta (is_hidden)';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/
\set SQLTERM ;
